// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;
    address deployer;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address target, bytes memory data, uint256 sendValue, bool callWithdraw, bool callCommand) internal {
        sendValue = bound(sendValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendValue);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 balanceAfterWithdraw = address(c).balance;
        bool commandReverted;
        vm.assume(address(this).balance >= sendValue);
        try c.Command{value: sendValue}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }
        uint256 balanceAfterCommand = address(c).balance;
        bool isOwner = (ownerBefore == address(this));
        assertTrue(isOwner || (withdrawReverted && commandReverted && balanceAfterWithdraw >= balanceBefore && balanceAfterCommand >= balanceAfterWithdraw));
    }

    function testFuzz_run(address target, bytes memory data, uint256 sendValue, bool callWithdraw, bool callCommand) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, data, sendValue, callWithdraw, callCommand);
    }

    receive() external payable {}
}
